{"command": "cd /workspace && cat > src/pp.c <<'PPC_EOF'
/* Tiny C Compiler - lexer and preprocessor */
#include "tcc.h"

/* ---------------- dynamic strings ---------------- */
void cstr_new(CString *s) { s->data = NULL; s->size = 0; s->allocated = 0; }
void cstr_free(CString *s) { free(s->data); s->data = NULL; s->size = s->allocated = 0; }
void cstr_reserve(CString *s, int size) {
    if (size > s->allocated) {
        int n = s->allocated ? s->allocated * 2 : 64;
        while (n < size) n *= 2;
        s->data = realloc(s->data, n);
        s->allocated = n;
    }
}
void cstr_ccat(CString *s, int ch) {
    cstr_reserve(s, s->size + 1);
    ((char *)s->data)[s->size++] = ch;
}
void cstr_cat(CString *s, const char *t) { while (*t) cstr_ccat(s, *t++); }
void cstr_cprintf(CString *s, const char *fmt, ...) {
    char buf[4096]; va_list ap; int n;
    va_start(ap, fmt); n = vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
    if (n < 0) n = 0;
    if (n >= (int)sizeof(buf)) n = sizeof(buf) - 1;
    cstr_cat(s, buf);
}

void *tcc_malloc(int size) { return malloc(size ? size : 1); }
void *tcc_realloc(void *p, int size) { return realloc(p, size ? size : 1); }

/* ---------------- error reporting ---------------- */
static int error_count;
int tcc_get_error_count(void) { return error_count; }

static const char *err_file_name = NULL;
static int err_line;

/* the currently active file/line for error messages */
extern BufFile *pp_cur_file;
BufFile *pp_cur_file;
int pp_out_line;
static int line_is_open;

static void pp_print_raw(const char *s) { fputs(s, stdout); }
static void pp_print_ch(int c) { fputc(c, stdout); }

void pp_flush_line(void) {
    if (line_is_open) { pp_print_ch('\n'); line_is_open = 0; }
}

/* emit catch-up newlines or a line marker before printing something at
   (line) in the current file */
static void pp_catchup(int line, BufFile *f) {
    int d;
    if (!f) f = pp_cur_file;
    if (!f) return;
    d = line - pp_out_line - 1;
    if (d < 0) d = 0;
    if (d > 7) {
        pp_flush_line();
        printf("# %d \"%s\"\n", line, f->filename);
        line_is_open = 0;
    } else {
        while (d-- > 0) pp_print_ch('\n');
        if (d < 0) { }
    }
    pp_out_line = line;
    line_is_open = 0;
}

/* print a token in -E mode */
static void pp_print_token(Token *t) {
    if (t->tok == TOK_EOF) return;
    pp_catchup(t->line, NULL);
    if (t->spc) pp_print_raw(t->spc);
    pp_print_raw(t->text);
    pp_out_line = t->line;
    line_is_open = 1;
}

/* print a file marker:  flags 1 = enter, 2 = return */
static void pp_print_marker(int line, const char *name, int flags, int catchup_to) {
    if (catchup_to) pp_catchup(catchup_to, NULL);
    else pp_flush_line();
    if (flags) printf("# %d \"%s\" %d\n", line, name, flags);
    else printf("# %d \"%s\"\n", line, name);
    pp_out_line = line;
}

void tcc_error(const char *fmt, ...) {
    va_list ap;
    const char *fn;
    int ln;
    fn = pp_cur_file ? pp_cur_file->filename : "?";
    ln = pp_cur_file ? pp_cur_file->line : 0;
    if (error_count == 0) {
        /* show include stack */
        BufFile *f;
        for (f = pp_cur_file ? pp_cur_file->prev : NULL; f; f = f->prev) {
            if (f->filename && strcmp(f->filename, "<command line>") != 0)
                printf("In file included from %s:%d:\n", f->filename, f->line);
        }
    }
    if (preprocess_only) pp_flush_line();
    error_count++;
    fprintf(stderr, "%s:%d: error: ", fn, ln);
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
    fprintf(stderr, "\n");
    fflush(stderr);
    longjmp(tcc_jmp_buf, 1);
}
PPC_EOF
echo "partial write""}

