/* Tiny C Compiler - lexer and preprocessor */
#include "tcc.h"
#include <setjmp.h>

/* ---------------- dynamic strings ---------------- */
void cstr_new(CString *s) { s->data = NULL; s->size = 0; s->allocated = 0; }
void cstr_free(CString *s) { free(s->data); s->data = NULL; s->size = s->allocated = 0; }
void cstr_reserve(CString *s, int size) {
    if (size > s->allocated) {
        int n = s->allocated ? s->allocated * 2 : 64;
        while (n < size) n *= 2;
        s->data = realloc(s->data, n);
        s->allocated = n;
    }
}
void cstr_ccat(CString *s, int ch) {
    cstr_reserve(s, s->size + 1);
    ((char *)s->data)[s->size++] = ch;
}
void cstr_cat(CString *s, const char *t) { while (*t) cstr_ccat(s, *t++); }
void cstr_cprintf(CString *s, const char *fmt, ...) {
    char buf[4096]; va_list ap; int n;
    va_start(ap, fmt); n = vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
    if (n < 0) n = 0;
    if (n >= (int)sizeof(buf)) n = sizeof(buf) - 1;
    cstr_cat(s, buf);
}
void *tcc_malloc(int size) { return malloc(size ? size : 1); }
void *tcc_realloc(void *p, int size) { return realloc(p, size ? size : 1); }

/* ---------------- error reporting ---------------- */
jmp_buf tcc_jmp_buf;
int tcc_state_initialized;
int preprocess_only;
int macro_list_mode;      /* -dM */
int macro_debug_mode;     /* -dD */
static int error_count;

extern BufFile *pp_cur_file;
BufFile *pp_cur_file;
int pp_out_line;
static int line_is_open;

static void pp_print_raw(const char *s) { fputs(s, stdout); }

void pp_flush_line(void) {
    if (line_is_open) { fputc('\n', stdout); line_is_open = 0; }
}

static void pp_catchup(int line, BufFile *f) {
    int d;
    if (!f) f = pp_cur_file;
    if (!f) return;
    d = line - pp_out_line - 1;
    if (d < 0) d = 0;
    if (d > 7) {
        pp_flush_line();
        printf("# %d \"%s\"\n", line, f->filename);
        line_is_open = 0;
    } else {
        while (d-- > 0) fputc('\n', stdout);
        line_is_open = 0;
    }
    pp_out_line = line;
}

static void pp_print_token(Token *t) {
    if (t->tok == TOK_EOF) return;
    pp_catchup(t->line, NULL);
    if (t->spc) pp_print_raw(t->spc);
    pp_print_raw(t->text);
    pp_out_line = t->line;
    line_is_open = 1;
}

/* flags: 1 = enter file, 2 = return to file, 0 = line marker */
static void pp_print_marker(int line, const char *name, int flags, int catchup_to) {
    if (catchup_to) pp_catchup(catchup_to, NULL);
    else pp_flush_line();
    if (flags) printf("# %d \"%s\" %d\n", line, name, flags);
    else printf("# %d \"%s\"\n", line, name);
    pp_out_line = line;
    line_is_open = 0;
}

void tcc_error_noabort(const char *fmt, ...) {
    va_list ap;
    const char *fn;
    int ln;
    fn = pp_cur_file ? pp_cur_file->filename : "?";
    ln = pp_cur_file ? pp_cur_file->line : 0;
    if (error_count == 0) {
        BufFile *f;
        for (f = pp_cur_file ? pp_cur_file->prev : NULL; f; f = f->prev) {
            if (f->filename && strcmp(f->filename, "<command line>") != 0 &&
                strcmp(f->filename, "-") != 0)
                printf("In file included from %s:%d:\n", f->filename, f->line);
        }
    }
    error_count++;
    if (preprocess_only) {
        pp_flush_line();
        fputc('\n', stdout);
        line_is_open = 0;
        fflush(stdout);
    }
    fprintf(stderr, "%s:%d: error: ", fn, ln);
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
    fprintf(stderr, "\n");
    fflush(stderr);
}

void tcc_error(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "tcc: error: ");
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fprintf(stderr, "\n");
    fflush(stderr);
    exit(1);
}

void tcc_warning(const char *fmt, ...) {
    va_list ap;
    fprintf(stderr, "tcc: warning: ");
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
    fprintf(stderr, "\n");
    fflush(stderr);
}

/* ---------------- ident table ---------------- */
#define TOK_HASH_SIZE 8192
static TokenSym *tok_hash[TOK_HASH_SIZE];
static TokenSym *tok_first, *tok_last;
static int tok_id_next = TOK_IDENT;

static unsigned int tok_hash_calc(const char *s, int len) {
    unsigned int h = 0;
    while (len--) h = h * 263 + (unsigned char)*s++;
    return h;
}

TokenSym *tok_alloc_new(const char *name, int len) {
    TokenSym *ts;
    unsigned int h = tok_hash_calc(name, len) % TOK_HASH_SIZE;
    ts = tcc_malloc(sizeof(TokenSym) + len);
    ts->tok = tok_id_next++;
    ts->hash = h;
    ts->len = len;
    memcpy(ts->str, name, len);
    ts->str[len] = 0;
    ts->hash_next = tok_hash[h];
    tok_hash[h] = ts;
    ts->sym_next = NULL;
    if (tok_last) tok_last->sym_next = ts; else tok_first = ts;
    tok_last = ts;
    return ts;
}

TokenSym *tok_lookup(const char *name, int len) {
    TokenSym *ts;
    unsigned int h = tok_hash_calc(name, len) % TOK_HASH_SIZE;
    for (ts = tok_hash[h]; ts; ts = ts->hash_next)
        if (ts->len == len && memcmp(ts->str, name, len) == 0) return ts;
    return NULL;
}

/* get-or-create */
TokenSym *tok_alloc(const char *name, int len) {
    TokenSym *ts = tok_lookup(name, len);
    if (ts) return ts;
    return tok_alloc_new(name, len);
}
