    BufFile *bf;
    CString s;
    int c;
    cstr_new(&s);
    while ((c = getchar()) != EOF) cstr_ccat(&s, c);
    bf = tcc_malloc(sizeof(BufFile));
    bf->buf_len = s.size;
    bf->buf = tcc_malloc(s.size + 1);
    if (s.size) memcpy(bf->buf, s.data, s.size);
    bf->buf[s.size] = 0;
    cstr_free(&s);
    bf->pos = 0;
    bf->line = 1;
    bf->filename = strdup("-");
    bf->is_stdin = 1;
    bf->prev = file;
    bf->include_next = 0;
    return bf;
}

static void tcc_push_file(BufFile *bf) {
    bf->prev = file;
    file = bf;
    pp_cur_file = bf;
    clear_pushback();
    if (preprocess_only && !macro_list_mode)
        pp_print_marker(1, bf->filename, 1, 0);
}

static void tcc_pop_file(void) {
    BufFile *bf = file;
    if (!bf) return;
    file = bf->prev;
    pp_cur_file = file;
    clear_pushback();
    if (preprocess_only && !macro_list_mode && file)
        pp_print_marker(file->line, file->filename, 2, 0);
}

