        if (c2 == '\r' && f->pos + 1 < f->buf_len && f->buf[f->pos+1] == '\n') {
            f->pos += 2; f->line++; return src_getc();
        }
        if (c2 == '\r') { f->pos++; f->line++; return src_getc(); }
    }
    return c;
}
