/* ---------------- macro expansion ---------------- */
typedef struct TokenList {
    Token *toks; int len, cap;
} TokenList;

static void tl_init(TokenList *l) { l->toks = NULL; l->len = l->cap = 0; }
static void tl_free(TokenList *l) { free(l->toks); l->toks = NULL; l->len = l->cap = 0; }
static void tl_add(TokenList *l, const Token *t) {
    if (l->len >= l->cap) {
        l->cap = l->cap ? l->cap * 2 : 16;
        l->toks = realloc(l->toks, l->cap * sizeof(Token));
    }
    l->toks[l->len++] = *t;
}

typedef struct ExpFrame {
    Token *toks;
    int len, pos;
    struct ExpFrame *prev;
} ExpFrame;
static ExpFrame *exp_top;

static Token pushback_tok;
static int pushback_valid;

static void save_tok(Token *t) {
    t->tok = tok; t->ival = tok_ival; t->fval = tok_fval;
    t->text = tok_text; t->spc = tok_spc; t->line = tok_line;
    t->sym = tok_sym; t->flags = tok_flags; t->raw = tok_str; t->len = tok_str_len;
}
static void load_tok(const Token *t) {
    tok = t->tok; tok_ival = t->ival; tok_fval = t->fval;
    tok_text = t->text; tok_spc = t->spc; tok_line = t->line;
    tok_sym = t->sym; tok_flags = t->flags; tok_str = t->raw; tok_str_len = t->len;
}

static void next_raw(void) {
    Token *t;
    if (pushback_valid) { pushback_valid = 0; load_tok(&pushback_tok); return; }
    if (exp_top) {
        if (exp_top->pos >= exp_top->len) {
            ExpFrame *f = exp_top;
            exp_top = f->prev;
            free(f->toks); free(f);
            next_raw();
            return;
        }
        t = &exp_top->toks[exp_top->pos++];
        load_tok(t);
        tok_line_start = 0;
        return;
    }
    for (;;) {
        lex();
        if (tok == TOK_EOF) {
            if (file) {
                tcc_pop_file();
                if (file) continue;
            }
            return;
        }
        return;
    }
}

/* lex a string into tokens (used for -D values and paste) */
static void lex_text_tokens(const char *s, TokenList *out) {
    BufFile *bf;
    Token t;
    save_tok(&t);
    bf = tcc_malloc(sizeof(BufFile));
    bf->buf_len = strlen(s);
    bf->buf = strdup(s);
    bf->pos = 0; bf->line = 1; bf->filename = strdup("<command line>");
    bf->prev = file; bf->is_stdin = 0; bf->include_next = 0;
    file = bf; pp_cur_file = bf;
    clear_pushback();
    tl_init(out);
    for (;;) {
        Token t2;
        lex();
        if (tok == TOK_EOF) break;
        save_tok(&t2);
        tl_add(out, &t2);
    }
    tcc_pop_file();
    load_tok(&t);
}

/* ---------------- macro definitions ---------------- */
static Macro *new_macro(TokenSym *sym) {
    Macro *m = tcc_malloc(sizeof(Macro));
    m->sym = sym;
    m->nargs = -1;
    m->va = 0;
    m->body = NULL;
    m->body_len = 0;
    m->str = NULL;
    m->line = 0;
    m->used = 0;
    sym->macro = m;
    return m;
}

#define MAX_ARGS 64

typedef struct {
    TokenSym *syms[MAX_ARGS];
    int nargs;
    int va;
    Token args[MAX_ARGS];
    int arglen[MAX_ARGS];
} MacroArgs;

static MacroArgs *collect_args(TokenSym *sym) {
    MacroArgs *a = tcc_malloc(sizeof(MacroArgs));
    TokenList cur;
    int depth = 0, i;
    int name_idx = 0;
    Token t;
    a->nargs = 0; a->va = 0;
    for (i = 0; i < MAX_ARGS; i++) { a->arglen[i] = 0; a->args[i].tok = 0; }
    tl_init(&cur);
    /* the '(' was already consumed by the caller */
    for (;;) {
        next_raw();
        if (tok == TOK_EOF) { tcc_error_noabort("macro '%s' used without args", sym->str); return a; }
        if (tok == ')' && depth == 0) break;
        if (tok == '(') depth++;
        else if (tok == ')') depth--;
        else if (tok == ',' && depth == 0) {
            if (a->nargs < MAX_ARGS) {
                a->syms[a->nargs] = NULL;
                a->args[a->nargs] = cur.toks ? cur.toks[0] : (Token){0};
                a->arglen[a->nargs] = cur.len;
                /* store the arg tokens */
                {
                    Token *arr = tcc_malloc((cur.len ? cur.len : 1) * sizeof(Token));
                    if (cur.len) memcpy(arr, cur.toks, cur.len * sizeof(Token));
                    else arr[0].tok = 0;
                    a->args[a->nargs].raw = (char*)arr;
                    a->args[a->nargs].len = cur.len;
                }
                a->nargs++;
            }
            tl_free(&cur); tl_init(&cur);
            continue;
        }
        /* drop leading whitespace of each argument */
        {
            Token nt; save_tok(&nt);
            if (cur.len == 0) nt.spc = NULL;
            if (cur.len < MAX_ARGS) { }
            tl_add(&cur, &nt);
        }
    }
    if (a->nargs < MAX_ARGS) {
        Token *arr = tcc_malloc((cur.len ? cur.len : 1) * sizeof(Token));
        if (cur.len) memcpy(arr, cur.toks, cur.len * sizeof(Token));
        else arr[0].tok = 0;
        a->args[a->nargs].raw = (char*)arr;
        a->args[a->nargs].len = cur.len;
        a->syms[a->nargs] = NULL;
        a->nargs++;
    }
    tl_free(&cur);
    (void)name_idx;
    return a;
}
PPC_EOF
