/* ---------------- macro expansion ---------------- */
typedef struct TokenList {
    Token *toks; int len, cap;
} TokenList;

static void tl_init(TokenList *l) { l->toks = NULL; l->len = l->cap = 0; }
static void tl_free(TokenList *l) { free(l->toks); l->toks = NULL; l->len = l->cap = 0; }
static void tl_add(TokenList *l, const Token *t) {
    if (l->len >= l->cap) {
        l->cap = l->cap ? l->cap * 2 : 16;
        l->toks = realloc(l->toks, l->cap * sizeof(Token));
    }
    l->toks[l->len++] = *t;
}

typedef struct ExpFrame {
    Token *toks;
    int len, pos;
    struct ExpFrame *prev;
} ExpFrame;
static ExpFrame *exp_top;

static Token pushback_tok;
static int pushback_valid;

#define MAX_ARGS 64

typedef struct MacroArgs {
    Token *arg[MAX_ARGS];
    int arglen[MAX_ARGS];
    int nargs;
    int va;
    int from_text[MAX_ARGS];
} MacroArgs;

static void save_tok(Token *t) {
    t->tok = tok; t->ival = tok_ival; t->fval = tok_fval;
    t->text = tok_text; t->spc = tok_spc; t->line = tok_line;
    t->sym = tok_sym; t->flags = tok_flags; t->raw = tok_str; t->len = tok_str_len;
}
static void load_tok(const Token *t) {
    tok = t->tok; tok_ival = t->ival; tok_fval = t->fval;
    tok_text = t->text; tok_spc = t->spc; tok_line = t->line;
    tok_sym = t->sym; tok_flags = t->flags; tok_str = t->raw; tok_str_len = t->len;
}

