/* ---------------- expansion builder ---------------- */
static void exp_add(TokenList *out, const Token *t) { tl_add(out, t); }

static int is_param(Macro *m, Token *t, MacroArgs *a) {
    int i;
    if (!t->sym) return -1;
    if (m->va && strcmp(t->sym->str, "__VA_ARGS__") == 0) return m->nargs;
    for (i = 0; i < m->nargs; i++)
        if (m->body_params[i] == t->sym) return i;
    return -1;
}

static void paste_tok(TokenList *out, Token *left, Token *right) {
    char *s = tcc_malloc(strlen(left->text) + strlen(right->text) + 1);
    TokenList tl;
    int i;
    strcpy(s, left->text); strcat(s, right->text);
    lex_text_tokens(s, &tl);
    for (i = 0; i < tl.len; i++) {
        Token t = tl.toks[i];
        t.flags |= TF_PASTED | TF_NOEXPAND;
        t.line = left->line;
        t.spc = NULL;
        exp_add(out, &t);
    }
    free(s);
    tl_free(&tl);
}

static void expand_macro_body(TokenSym *sym, Macro *m, MacroArgs *a, int inv_line,
                              const char *inv_spc, TokenList *out) {
    int i;
    Token *b = m->body;
    int n = m->body_len;
    int first = 1;
    for (i = 0; i < n; i++) {
        Token t = b[i];
        int pi;
        if (t.tok == TOK_SHARP && i + 1 < n) {
            int pj = is_param(m, &b[i+1], a);
            if (pj >= 0) {
                Token s;
                char *str = stringify_arg(a->arg[pj], a->arglen[pj]);
                memset(&s, 0, sizeof(s));
                s.tok = TOK_STR;
                s.text = str;
                s.spc = first ? inv_spc : t.spc;
                s.line = inv_line;
                s.raw = str + 1;
                s.len = strlen(str + 1) - 1;
                s.line_start = 0;
                exp_add(out, &s);
                first = 0;
                i++;
                continue;
            }
        }
        if (t.tok == TOK_TWOSHARPS && i + 1 < n) {
            int pj = is_param(m, &b[i+1], a);
            Token right;
            if (out->len == 0) continue;
            if (pj >= 0) {
                int al = a->arglen[pj];
                int k;
                if (al == 0) { i++; continue; }
                right = a->arg[pj][0];
                if (al > 1) {
                    /* paste only with the first token; append the rest */
                    Token rest[64]; int rn = 0;
                    paste_tok(out, &out->toks[out->len-1], &right);
                    for (k = 1; k < al && rn < 64; k++) rest[rn++] = a->arg[pj][k];
                    for (k = 0; k < rn; k++) exp_add(out, &rest[k]);
                } else paste_tok(out, &out->toks[out->len-1], &right);
                i++;
                continue;
            } else {
                right = b[i+1];
                paste_tok(out, &out->toks[out->len-1], &right);
                i++;
                continue;
            }
        }
        pi = is_param(m, &t, a);
        if (pi >= 0) {
            int al = a->arglen[pi];
            int k;
            if (al == 0) continue;
            for (k = 0; k < al; k++) {
                Token at = a->arg[pi][k];
                if (first) { at.spc = inv_spc; }
                at.line = inv_line;
                at.line_start = 0;
                exp_add(out, &at);
            }
            first = 0;
            continue;
        }
        if (first) { t.spc = inv_spc; }
        t.line = inv_line;
        t.line_start = 0;
        if (t.sym == sym) t.flags |= TF_NOEXPAND;
        exp_add(out, &t);
        first = 0;
    }
    /* GNU comma paste */
    if (m->va && a->va && a->arglen[m->nargs] == 0 && out->len >= 2) {
        if (out->toks[out->len-2].tok == ',' && out->toks[out->len-1].flags & TF_PASTED) { }
    }
    if (out->len > 0 && out->toks[0].spc == NULL) out->toks[0].spc = inv_spc;
}
PPC_EOF
echo ok"}

