cd /workspace && cat >> src/pp.c <<'PPC_EOF'

/* ---------------- #if expression evaluation ---------------- */
typedef struct { Token *toks; int len; int pos; } ExprState;

static void expr_error(TokenList *l, int is_if) {
    CString s;
    int i;
    cstr_new(&s);
    cstr_cat(&s, is_if ? "#if" : "#elif");
    for (i = 0; i < l->len; i++) {
        cstr_ccat(&s, ' ');
        cstr_cat(&s, l->toks[i].text);
    }
    cstr_ccat(&s, 0);
    tcc_error_noabort("bad preprocessor expression: %s", s.data);
}

static long long expr_primary(ExprState *e, TokenList *l) {
    Token *t;
    if (e->pos >= l->len) { expr_error(l, 1); return 0; }
    t = &l->toks[e->pos++];
    switch (t->tok) {
    case TOK_CINT: case TOK_CCHAR: case TOK_LCHAR:
    case TOK_CUINT: case TOK_CLLONG: case TOK_CULLONG:
        return (long long)t->ival;
    case TOK_CFLOAT: case TOK_CDOUBLE: case TOK_CLDOUBLE:
        return (long long)t->fval;
    case '(': {
        long long v = expr_or(e, l);
        if (e->pos >= l->len || l->toks[e->pos].tok != ')') { expr_error(l,1); return 0; }
        e->pos++;
        return v;
    }
    default:
        expr_error(l, 1);
        return 0;
    }
}

static long long expr_unary(ExprState *e, TokenList *l) {
    if (e->pos >= l->len) { expr_error(l,1); return 0; }
    switch (l->toks[e->pos].tok) {
    case '!': e->pos++; return !expr_unary(e, l);
    case '-': e->pos++; return -expr_unary(e, l);
    case '+': e->pos++; return expr_unary(e, l);
    case '~': e->pos++; return ~expr_unary(e, l);
    default: return expr_primary(e, l);
    }
}
#define BINOP(f) \
static long long f(ExprState *e, TokenList *l) { \
    long long a = e##_up(e, l); \
    while (e->pos < l->len) { int t = l->toks[e->pos].tok; ... } \
    return a; }
PPC_EOF
echo ok

