    m->nargs = is_func ? nargs : -1;
    m->va = va;
    m->body = body.toks;
    m->body_len = body.len;
    m->line = pp_directive_line;
    for (i = 0; i < params.len && i < 64; i++) m->body_params[i] = params.toks[i].sym;
