cd /workspace && cat >> src/pp.c <<'PPC_EOF'

/* ---------------- directives ---------------- */
static int pp_directive_line;
static int print_depth = 0;

static void skip_rest_of_line(void) {
    for (;;) {
        if (tok == TOK_EOF) return;
        if (tok_line != pp_directive_line) {
            Token t; save_tok(&t); pushback_tok = t; pushback_valid = 1;
            return;
        }
        next();
    }
}

static void consume_rest_of_line_raw(void) {
    /* consume tokens and the trailing newline (for #include) */
    int c;
    for (;;) {
        if (tok == TOK_EOF) return;
        if (tok_line != pp_directive_line) return;
        next_raw();
        if (tok == TOK_EOF) return;
    }
    (void)c;
}

static void skip_cond_block(void) {
    int n = 0;
    for (;;) {
        next_raw();
        if (tok == TOK_EOF) {
            tcc_error_noabort("#endif missing");
            return;
        }
        if (tok == TOK_SHARP && tok_line_start) {
            int dline = tok_line;
            next_raw();
            if (tok != TOK_EOF && tok_sym) {
                const char *d = tok_sym->str;
                if (!strcmp(d, "if") || !strcmp(d, "ifdef") || !strcmp(d, "ifndef")) n++;
                else if (n == 0 && (!strcmp(d, "elif") || !strcmp(d, "else") || !strcmp(d, "endif"))) {
                    /* process this directive (tok is the name) */
                    pp_directive_line = dline;
                    handle_pp();
                    return;
                }
                else if (!strcmp(d, "endif")) n--;
            }
            /* skip to the end of the line */
            {
                int save_depth = print_depth;
                print_depth++;
                skip_rest_of_line();
                print_depth = save_depth;
            }
        }
    }
}

static void pp_define(void) {
    TokenSym *sym;
    Macro *m;
    TokenList params, body;
    int va = 0, nargs = 0, is_func = 0;
    tl_init(&params); tl_init(&body);
    next_raw();
    if (!(tok >= TOK_IDENT)) {
        tcc_error_noabort("invalid macro name '%s'", tok_text);
        skip_rest_of_line();
        return;
    }
    sym = tok_sym;
    if (tok_sym->macro) { /* redefinition: keep the old one */ }
    next_raw();
    if (tok == '(' && (!tok_spc || !tok_spc[0])) {
        is_func = 1;
        for (;;) {
            next_raw();
            if (tok == TOK_EOF) { tcc_error_noabort("invalid macro name '%s'", sym->str); break; }
            if (tok == ')') break;
            if (tok == TOK_DOTDOTDOT) { va = 1; continue; }
            if (tok >= TOK_IDENT) {
                if (params.len < MAX_ARGS) {
                    Token t; save_tok(&t); tl_add(&params, &t);
                }
                nargs++;
            } else if (tok == ',') continue;
            else { tcc_error_noabort("invalid macro name '%s'", tok_text); }
        }
    } else {
        /* push back the token */
        Token t; save_tok(&t); pushback_tok = t; pushback_valid = 1;
    }
    /* the body: tokens until the end of the line */
    for (;;) {
        if (tok == TOK_EOF) break;
        if (tok_line != pp_directive_line) {
            Token t; save_tok(&t); pushback_tok = t; pushback_valid = 1;
            break;
        }
        {
