static void pp_undef(void) {
    next_raw();
    if (tok >= TOK_IDENT && tok_sym) tok_sym->macro = NULL;
    skip_rest_of_line();
}

static void pp_if_expr(int is_if) {
    TokenList l;
    ExprState e;
    int val = 0;
    int parent_skip = (cond_n > 0 && cond_stack[cond_n-1].cond == 0);
    int start_line = pp_directive_line;
    int save_depth = print_depth;
    print_depth++;
    tl_init(&l);
    if (!parent_skip) read_expr_tokens(&l, start_line);
    else skip_rest_of_line();
    print_depth = save_depth;
    if (parent_skip) {
        cond_stack[cond_n].cond = 0; cond_stack[cond_n].taken = 1;
        cond_stack[cond_n].in_else = 0; cond_stack[cond_n].dummy = 1;
        cond_n++;
        return;
    }
    e.toks = l.toks; e.len = l.len; e.pos = 0;
    if (l.len == 0) { tcc_error_noabort(is_if ? "missing #if expression" : "missing #elif expression"); val = 0; }
    else val = (expr_level(&e, &l, 0) != 0);
    cond_stack[cond_n].cond = val; cond_stack[cond_n].taken = val;
    cond_stack[cond_n].in_else = 0; cond_stack[cond_n].dummy = 0;
    cond_n++;
    tl_free(&l);
    if (!val) skip_cond_block();
}

static void pp_ifdef(int want) {
    int val;
    next_raw();
    if (!(tok >= TOK_IDENT)) { tcc_error_noabort("invalid argument for '%s'", want ? "#ifdef" : "#ifndef"); val = 0; }
    else val = tok_sym->macro ? 1 : 0;
    skip_rest_of_line();
    if (cond_n > 0 && cond_stack[cond_n-1].cond == 0) {
        cond_stack[cond_n].cond = 0; cond_stack[cond_n].taken = 1;
        cond_stack[cond_n].in_else = 0; cond_stack[cond_n].dummy = 1;
        cond_n++;
        return;
    }
    val = (val == want) ? 1 : 0;
    cond_stack[cond_n].cond = val; cond_stack[cond_n].taken = val;
    cond_stack[cond_n].in_else = 0; cond_stack[cond_n].dummy = 0;
    cond_n++;
    if (!val) skip_cond_block();
}

static void pp_elif(void) {
    TokenList l;
    ExprState e;
    int val = 0;
    CState *s;
    int start_line = pp_directive_line;
    int parent_skip = (cond_n > 1 && cond_stack[cond_n-2].cond == 0);
    int save_depth = print_depth;
    if (cond_n == 0) { tcc_error_noabort("#elif without matching #if"); skip_rest_of_line(); return; }
    s = &cond_stack[cond_n-1];
    print_depth++;
    tl_init(&l);
    if (!parent_skip && !s->cond && !s->taken) read_expr_tokens(&l, start_line);
    else skip_rest_of_line();
    print_depth = save_depth;
    if (parent_skip) { s->cond = 0; s->taken = 1; return; }
    if (s->in_else) { tcc_error_noabort("#elif after #else"); return; }
    if (s->cond) { s->cond = 0; skip_cond_block(); return; }
    if (!s->taken) {
        e.toks = l.toks; e.len = l.len; e.pos = 0;
        if (l.len == 0) { tcc_error_noabort("missing #elif expression"); val = 0; }
        else val = (expr_level(&e, &l, 0) != 0);
        s->cond = val; s->taken |= val;
        tl_free(&l);
        if (!val) skip_cond_block();
        return;
    }
    s->cond = 0;
    skip_cond_block();
}

static void pp_else(void) {
    CState *s;
    int parent_skip = (cond_n > 1 && cond_stack[cond_n-2].cond == 0);
    if (cond_n == 0) { tcc_error_noabort("#else without matching #if"); skip_rest_of_line(); return; }
    s = &cond_stack[cond_n-1];
    skip_rest_of_line();
    if (parent_skip) { s->cond = 0; s->taken = 1; return; }
    if (s->in_else) { tcc_error_noabort("#else after #else"); return; }
    s->in_else = 1;
    if (s->cond) { s->cond = 0; skip_cond_block(); return; }
    if (!s->taken) { s->cond = 1; s->taken = 1; return; }
    s->cond = 0;
    skip_cond_block();
}

static void pp_endif(void) {
    if (cond_n == 0) { tcc_error_noabort("#endif without matching #if"); skip_rest_of_line(); return; }
    cond_n--;
    skip_rest_of_line();
}

static void line_text(CString *s) {
    /* append the rest of the directive line as tokens joined with single spaces */
    int first = 1;
    for (;;) {
        if (tok == TOK_EOF) break;
        if (tok_line != pp_directive_line) {
            Token t; save_tok(&t); pushback_tok = t; pushback_valid = 1;
            break;
        }
        if (!first) cstr_ccat(s, ' ');
        cstr_cat(s, tok_text);
        first = 0;
        next();
    }
}

static void pp_error(int is_warning) {
    CString s;
    cstr_new(&s);
    cstr_ccat(&s, '#');
    cstr_cat(&s, is_warning ? "warning " : "error ");
    line_text(&s);
    cstr_ccat(&s, 0);
    if (is_warning) tcc_warning("%s", s.data);
    else tcc_error_noabort("%s", s.data);
    cstr_free(&s);
}

static void pp_pragma(void) {
    TokenList l;
    int j;
    int save_depth = print_depth;
    print_depth++;
    tl_init(&l);
    for (;;) {
        Token t;
        if (tok == TOK_EOF) break;
        if (tok_line != pp_directive_line) { save_tok(&t); pushback_tok = t; pushback_valid = 1; break; }
        save_tok(&t); tl_add(&l, &t);
        next();
    }
    print_depth = save_depth;
    if (l.len > 0 && l.toks[0].sym && strcmp(l.toks[0].sym->str, "once") == 0) {
        file->pragma_once = 1;
    } else if (l.len > 0 && l.toks[0].sym && strcmp(l.toks[0].sym->str, "pack") == 0) {
        /* ignore */
    } else {
        /* output the pragma as-is in -E mode */
        if (preprocess_only && !macro_list_mode) {
            CString s;
            cstr_new(&s);
            cstr_cat(&s, "#pragma");
            for (j = 0; j < l.len; j++) { cstr_ccat(&s, ' '); cstr_cat(&s, l.toks[j].text); }
            cstr_ccat(&s, 0);
            pp_catchup(pp_directive_line, pp_cur_file);
            pp_print_raw(s.data);
            fputc('\n', stdout);
            line_is_open = 0;
            pp_out_line = pp_directive_line;
            cstr_free(&s);
        }
    }
    tl_free(&l);
}
