static void pp_include(int include_next) {
    int is_angle = 0;
    char *name, *path;
    BufFile *bf;
    if (pp_skipping()) { skip_rest_of_line(); return; }
    name = read_include_name(&is_angle);
    if (!name) { tcc_error_noabort("invalid directive"); skip_rest_of_line(); return; }
    path = search_include(name, is_angle, include_next);
    if (!path) {
        tcc_error_noabort("include file '%s' not found", name);
        consume_rest_of_line_nl();
        return;
    }
    bf = tcc_open_file(path, 0);
    if (!bf) {
        tcc_error_noabort("include file '%s' not found", name);
        consume_rest_of_line_nl();
        return;
    }
    consume_rest_of_line_nl();
    if (preprocess_only && !macro_list_mode) {
        if (pp_out_line < file->line) pp_catchup(file->line, file);
    }
    tcc_push_file(bf);
}

static void pp_line_directive(void) {
    int line = 0;
    const char *fn = NULL;
    int save_depth = print_depth;
    print_depth++;
    if (tok >= TOK_CINT && tok <= TOK_CLDOUBLE) { line = (int)tok_ival; next(); }
    if (tok == TOK_STR || tok == TOK_LSTR) { fn = tok_str; next(); }
    skip_rest_of_line();
    print_depth = save_depth;
    if (line) {
        file->line = line - 1;
        if (fn) { free(file->filename); file->filename = strdup(fn); }
    }
}

static void handle_pp(void) {
    const char *d;
    pp_directive_line = tok_line;
    next_raw();
    if (tok == TOK_EOF) return;
    if (tok < TOK_IDENT) {
        if (tok >= TOK_CINT && tok <= TOK_CLDOUBLE) { pp_line_directive(); return; }
        tcc_error_noabort("invalid directive");
        skip_rest_of_line();
        return;
    }
    d = tok_sym->str;
    if (!strcmp(d, "define")) pp_define();
    else if (!strcmp(d, "undef")) pp_undef();
    else if (!strcmp(d, "include")) { next_raw(); pp_include(0); }
    else if (!strcmp(d, "include_next")) { next_raw(); pp_include(1); }
    else if (!strcmp(d, "if")) pp_if_expr(1);
    else if (!strcmp(d, "ifdef")) pp_ifdef(1);
    else if (!strcmp(d, "ifndef")) pp_ifdef(0);
    else if (!strcmp(d, "elif")) pp_elif();
    else if (!strcmp(d, "else")) pp_else();
    else if (!strcmp(d, "endif")) pp_endif();
    else if (!strcmp(d, "error")) pp_error(0);
    else if (!strcmp(d, "warning")) pp_error(1);
    else if (!strcmp(d, "line")) pp_line_directive();
    else if (!strcmp(d, "pragma")) pp_pragma();
    else if (!strcmp(d, "assert") || !strcmp(d, "unassert") || !strcmp(d, "ident") ||
             !strcmp(d, "sccs") || !strcmp(d, "sassert")) skip_rest_of_line();
    else {
        skip_rest_of_line();
    }
}

/* ---------------- main token loop ---------------- */
void next(void) {
    for (;;) {
        int was_ls;
        next_raw();
        if (tok == TOK_EOF) break;
        was_ls = tok_line_start;
        if (tok == TOK_SHARP && was_ls) {
            handle_pp();
            continue;
        }
        if (tok >= TOK_IDENT && tok_sym && tok_sym->macro && !(tok_flags & TF_NOEXPAND)) {
            Macro *m = tok_sym->macro;
            if (m->nargs >= 0) {
                Token name_tok;
                save_tok(&name_tok);
                next_raw();
                if (tok == '(') {
                    MacroArgs *a = collect_args(tok_sym, m);
                    expand_and_push(tok_sym, m, a, name_tok.spc, name_tok.line);
                    continue;
                } else {
                    save_tok(&pushback_tok);
                    pushback_valid = 1;
                    load_tok(&name_tok);
                    break;
                }
            } else {
                expand_and_push(tok_sym, m, NULL, tok_spc, tok_line);
                continue;
            }
        }
        break;
    }
    if (preprocess_only && !macro_list_mode && print_depth == 0) {
        Token t;
        save_tok(&t);
        pp_print_token(&t);
    }
}
PPC_EOF
