/* ------------- option parsing ------------- */
static void add_file(const char *name, int type) {
    if (n_files < 1024) { in_files[n_files] = strdup(name); file_types[n_files] = type; n_files++; }
}

static const char *opt_arg(int argc, char **argv, int *i, const char *r, const char *name) {
    const char *rest = r + 1 + strlen(name);
    if (*rest) return rest;
    if (*i + 1 < argc) return argv[++(*i)];
    tcc_error_exit("argument to '-%s' is missing", name);
    return NULL;
}

/* returns 1 if this option does not require any input files */
static int is_noaction_option(const char *r) {
    if (r[1] == 'B') return 1;
    if (r[1] == 'm' && (r[2] == '6' || r[2] == '3')) return 1;
    return 0;
}

static void handle_option(int argc, char **argv, int *i, const char *r);

static void parse_arglist(int argc, char **argv) {
    int i;
    for (i = 0; i < argc; i++) {
        const char *r = argv[i];
        if (r[0] != '-' || r[1] == 0) {
            if (r[0] == '-' && r[1] == 0) { add_file("-", AFF_TYPE_C); continue; }
            add_file(r, 0);
            continue;
        }
        if (r[1] == '-' && r[2] == 0) continue;
        if (r[1] == '@') {
            /* read arguments from listfile */
            FILE *f = fopen(r + 2, "rb");
            char *buf; long sz;
            if (!f) tcc_error_exit("file '%s' not found", r + 2);
            fseek(f, 0, SEEK_END); sz = ftell(f); fseek(f, 0, SEEK_SET);
            buf = tcc_malloc(sz + 1);
            if (sz > 0 && fread(buf, 1, sz, f) != (size_t)sz) { }
            buf[sz] = 0;
            fclose(f);
            {   /* split on whitespace */
                char **args = tcc_malloc((sz + 2) * sizeof(char *));
                int n = 0, j = 0;
                while (j < sz) {
                    while (j < sz && (buf[j] == ' ' || buf[j] == '\n' || buf[j] == '\t' || buf[j] == '\r')) j++;
                    if (j >= sz) break;
                    args[n++] = buf + j;
                    while (j < sz && buf[j] != ' ' && buf[j] != '\n' && buf[j] != '\t' && buf[j] != '\r') j++;
                    buf[j++] = 0;
                }
                parse_arglist(n, args);
            }
            continue;
        }
        handle_option(argc, argv, &i, r);
    }
}

static void handle_option(int argc, char **argv, int *i, const char *r) {
    const char *opt = r + 1;
    char c = opt[0];
    if (c == 'o' && (opt[1] == 0 || opt[1] != 0)) {
        out_file = (char *)opt_arg(argc, argv, i, r, "o");
        action_count++;
        return;
    }
    if (c == 'I') { add_path(&inc_paths_user, opt_arg(argc, argv, i, r, "I")); return; }
    if (c == 'L') { tcc_add_lib_path(opt_arg(argc, argv, i, r, "L")); return; }
    if (c == 'B') { tcc_lib_path = strdup(opt_arg(argc, argv, i, r, "B")); return; }
    if (c == 'M' && opt[1] == 'F') {
        dep_file = (char *)opt_arg(argc, argv, i, r, "MF");
        return;
    }
    if (c == 'M') {
        if (opt[1] == 'M' && opt[2] == 'D') { dep_mode = 4; action_count++; return; }
        if (opt[1] == 'M') { dep_mode = 2; dep_only = 1; action_count++; return; }
        if (opt[1] == 'D') { dep_mode = 3; action_count++; return; }
        if (opt[1] == 0) { dep_mode = 1; dep_only = 1; action_count++; return; }
        tcc_error_exit("invalid option -- '%s'", r);
    }
    if (c == 'D') { add_cmd_define(opt_arg(argc, argv, i, r, "D")); action_count++; return; }
    if (c == 'U') { add_cmd_undef(opt_arg(argc, argv, i, r, "U")); action_count++; return; }
    if (c == 'I' || c == 'i') {
        if (opt[0] == 'i' && !strcmp(opt, "isystem")) {
            add_path(&inc_paths_system, opt_arg(argc, argv, i, r, "isystem"));
            return;
        }
        if (opt[0] == 'i' && !strcmp(opt, "include")) {
            if (n_pre_includes < 64) pre_includes[n_pre_includes++] = strdup(opt_arg(argc, argv, i, r, "include"));
            action_count++;
            return;
        }
    }
    if (!strcmp(opt, "c")) { output_type = TCC_OUTPUT_OBJ; action_count++; return; }
    if (!strcmp(opt, "r")) { output_type = TCC_OUTPUT_OBJ; action_count++; return; }
    if (!strcmp(opt, "E")) { output_type = TCC_OUTPUT_PREPROCESS; preprocess_only = 1; action_count++; return; }
    if (!strcmp(opt, "run")) { output_type = TCC_OUTPUT_MEMORY; action_count++; return; }
    if (!strcmp(opt, "shared")) { output_type = TCC_OUTPUT_DLL; action_count++; return; }
    if (!strcmp(opt, "static")) { static_link = 1; action_count++; return; }
    if (!strcmp(opt, "rdynamic")) { rdynamic = 1; action_count++; return; }
    if (!strcmp(opt, "nostdlib")) { nostdlib = 1; action_count++; return; }
    if (!strcmp(opt, "nostdinc")) { nostdinc = 1; no_stdinc = 1; action_count++; return; }
    if (!strcmp(opt, "soname")) { soname = (char *)opt_arg(argc, argv, i, r, "soname"); action_count++; return; }
    if (!strcmp(opt, "bench")) { do_bench = 1; action_count++; return; }
    if (!strcmp(opt, "w")) { warn_all = 2; action_count++; return; }
    if (!strcmp(opt, "v") || !strcmp(opt, "vv")) {
        int n = 0;
        while (opt[n] == 'v') n++;
        verbose += n;
        if (verbose == 1) printf("tcc version %s %s %s (%s)\n", TCC_VERSION, TCC_DATE, TCC_BUILD, TCC_ARCH_STR);
        return;
    }
