}

void handle_warn(const char *w, int set) {
    if (!strcmp(w, "all")) warn_all = set;
    else if (!strcmp(w, "error")) warn_error = set ? 1 : 0;
    else if (!strncmp(w, "error=", 6)) warn_error = set ? 2 : 0;
    else if (!strcmp(w, "write-strings")) warn_specific[WARN_write_strings] = set;
    else if (!strcmp(w, "unsupported")) warn_specific[WARN_unsupported] = set;
