    else if (!strcmp(f, "test-coverage")) test_coverage = set;
    else if (!strcmp(f, "bounds-check")) { }
    else if (!strcmp(f, "no-asm")) no_asm_flag = set;
    else if (!strcmp(f, "preprocess-only")) { }
    else if (!strcmp(f, "stdin")) { }
    else if (!strcmp(f, "pretell")) { }
    else tcc_warning("unsupported option '-f%s'", f);
}

void handle_warn(const char *w, int set) {
    if (!strcmp(w, "all")) warn_all = set;
    else if (!strcmp(w, "error")) warn_error = set ? 1 : 0;
    else if (!strncmp(w, "error=", 6)) warn_error = set ? 2 : 0;
    else if (!strcmp(w, "write-strings")) warn_specific[WARN_write_strings] = set;
    else if (!strcmp(w, "unsupported")) warn_specific[WARN_unsupported] = set;
    else if (!strcmp(w, "implicit-function-declaration")) warn_specific[WARN_implicit_func_decl] = set;
    else if (!strcmp(w, "discarded-qualifiers")) warn_specific[WARN_discarded_qualifiers] = set;
    else if (!strcmp(w, "no-all")) warn_all = 0;
    else if (!strcmp(w, "no-error")) warn_error = 0;
    else if (!strncmp(w, "no-error=", 9)) warn_error = 0;
    else tcc_warning("unsupported option '-W%s'", w);
}

static int str_startswith(const char *s, const char *p) {
    return strncmp(s, p, strlen(p)) == 0;
}

void handle_linker_option(const char *o) {
    if (!strcmp(o, "nostdlib")) { nostdlib = 1; return; }
    if (!strcmp(o, "whole-archive")) { whole_archive = 1; return; }
    if (!strcmp(o, "no-whole-archive")) { whole_archive = 0; return; }
    if (!strcmp(o, "export-all-symbols") || !strcmp(o, "export-dynamic")) { rdynamic = 1; return; }
    if (str_startswith(o, "image-base=")) { image_base = strtoull(o + 11, NULL, 0); return; }
    if (str_startswith(o, "Ttext=")) { text_addr = strtoull(o + 6, NULL, 0); return; }
    if (str_startswith(o, "section-alignment=")) { section_alignment = atoi(o + 18); return; }
    if (str_startswith(o, "rpath=")) { rpath = strdup(o + 6); return; }
    if (!strcmp(o, "enable-new-dtags")) { enable_new_dtags = 1; return; }
    if (str_startswith(o, "soname=")) { soname = strdup(o + 7); return; }
    if (str_startswith(o, "I")) { interp = strdup(o + 1); return; }
    if (str_startswith(o, "dynamic-linker=")) { interp = strdup(o + 15); return; }
    if (!strcmp(o, "Bsymbolic")) { symbolic_flag = 1; return; }
    if (str_startswith(o, "oformat=")) {
        const char *f = o + 8;
        if (strstr(f, "elf64")) output_format = 64;
        else if (strstr(f, "elf32")) output_format = 32;
        else if (strstr(f, "binary")) output_format = 0;
        return;
    }
    if (str_startswith(o, "init=") || str_startswith(o, "fini=") ||
        str_startswith(o, "Map=") || !strcmp(o, "as-needed") || !strcmp(o, "O") ||
        str_startswith(o, "z=") || str_startswith(o, "-")) return;
    tcc_error_exit("unsupported linker option '%s'", o);
}

void handle_pp_option(const char *o) {
    if (o[0] == 'P' && o[1] == '1') { pp_line_mode = 2; return; }
    if (o[0] == 'P') { pp_line_mode = 1; return; }
    if (o[0] == 'd' && o[1] == 'D') { macro_debug_mode = 1; return; }
    if (o[0] == 'd' && o[1] == 'M') { macro_list_mode = 1; return; }
    if (o[0] == 't') { dt_mode = 1; return; }
    tcc_warning("unsupported option '-Wp,%s'", o);
}

void handle_target_option(const char *t) {
    if (!strcmp(t, "32")) {
        char exe[4096];
        const char *p = strrchr(program_name, '/');
        snprintf(exe, sizeof(exe), "%.*s/i386-tcc", p ? (int)(p - program_name) : 0,
                 p ? program_name : "");
        execv(exe, saved_argv);
        tcc_error_nofmt("could not run '%s'", exe);
    } else if (!strcmp(t, "64")) {
        return;
    } else if (!strcmp(t, "ms-bitfields")) { ms_bitfields = 1; return; }
    else if (!strcmp(t, "no-sse")) { no_sse = 1; action_count++; return; }
    else tcc_warning("unsupported option '-m%s'", t);
}
MAIN_EOF
echo ok

