p=open('src/pp.c').read()
p=p.replace("""void tcc_push_cmdline(void) {
    BufFile *bf;
    if (!tcc_cmdline_text) return;""","""void tcc_push_cmdline(void) {
    BufFile *bf;
    if (getenv("TCC_DEBUG2")) fprintf(stderr, "CMDLINE len=%d first=<%.60s>\\n", (int)strlen(tcc_cmdline_text), tcc_cmdline_text);
    if (!tcc_cmdline_text) return;""")
open('src/pp.c','w').write(p)
PY
gcc -o /tmp/mytcc -Isrc src/pp.c src/main.c src/compile.c 2>&1|head -3; cd /tmp/t1 && TCC_DEBUG2=1 /tmp/mytcc -E -dD t2.c 2>&1 | head -6; echo "---- blob last lines"; python3 -c "
import re
s=open('/workspace/src/predefs.h').read()
# extract the string literal lines
lines=re.findall(r'\"((?:[^\"\\\\]|\\\\.)*)\"', s)
print(len(lines))
print(repr(lines[0]), repr(lines[-1]))
print(''.join(l+'\\\\n' for l in lines)[:200])
"

